def prepare_files() -> Path:
    APP_DIR.mkdir(parents=True, exist_ok=True)
    data = base64.b64decode("".join(ARCHIVE_B64))
    with zipfile.ZipFile(BytesIO(data)) as archive:
        archive.extractall(APP_DIR)

    # Patch the embedded server to honor Render's assigned port and public bind address.
    server = APP_DIR / "server.py"
    source = server.read_text(encoding="utf-8")
    source = source.replace(
        'PORT = int(os.environ.get("CS_UI_PORT", "20340"))',
        'PORT = int(os.environ.get("PORT", os.environ.get("CS_UI_PORT", "20340")))',
    )
    source = source.replace(
        'HOST = os.environ.get("CS_UI_HOST", "0.0.0.0")',
        'HOST = "0.0.0.0"',
    )
    server.write_text(source, encoding="utf-8")
    return APP_DIR

def main() -> None:
    root = prepare_files()

    try:
        import aiohttp
        import Crypto
        import google.protobuf
        import protobuf_decoder
        import urllib3
    except ImportError as exc:
        req_file = root / "requirements.txt"
        print(f"Missing dependency: {exc}", flush=True)
        print(f'Install with: "{sys.executable}" -m pip install -r "{req_file}"', flush=True)
        raise SystemExit(1)

    # Render supplies PORT dynamically; always listen on all network interfaces.
    port = os.environ.get("PORT", os.environ.get("CS_UI_PORT", "20340"))
    os.environ["PORT"] = str(port)
    os.environ["CS_UI_PORT"] = str(port)
    os.environ["CS_UI_HOST"] = "0.0.0.0"
    os.environ["PYTHONUNBUFFERED"] = "1"
    os.environ.setdefault("PROTOCOL_BUFFERS_PYTHON_IMPLEMENTATION", "python")

    os.chdir(root)
    sys.path.insert(0, str(root))
    print(f"[launcher] binding web service to 0.0.0.0:{port}", flush=True)
    runpy.run_path(str(root / "server.py"), run_name="__main__")

if __name__ == "__main__":
    main()
